import{_ as t}from"./chunks/image 2.Dyzhk9-H.js";import{_ as l,o as r,c as e,a3 as i}from"./chunks/framework.Bh_aNVBG.js";const b=JSON.parse('{"title":"3. 공지사항 등록 및 관리","description":"","frontmatter":{},"headers":[],"relativePath":"partner/chapter-3.md","filePath":"partner/chapter-3.md"}'),o={name:"partner/chapter-3.md"};function h(n,a,d,s,p,c){return r(),e("div",null,[...a[0]||(a[0]=[i('<h1 id="_3-공지사항-등록-및-관리" tabindex="-1">3. 공지사항 등록 및 관리 <a class="header-anchor" href="#_3-공지사항-등록-및-관리" aria-label="Permalink to &quot;3. 공지사항 등록 및 관리&quot;">​</a></h1><p>공지사항은 행사 운영과 관련된 중요한 정보를 방문객에게 전달하기 위한 기능입니다.</p><p>행사 시간 변경, 운영 안내, 시설 안내 및 긴급 공지 등 행사 운영에 필요한 정보를 등록하고 관리할 수 있습니다.</p><h2 id="_3-1-공지사항-관리-화면" tabindex="-1">3.1. 공지사항 관리 화면 <a class="header-anchor" href="#_3-1-공지사항-관리-화면" aria-label="Permalink to &quot;3.1. 공지사항 관리 화면&quot;">​</a></h2><p>파트너 관리 화면에서 <strong>공지사항</strong> 메뉴를 선택합니다.</p><p>공지사항 관리 화면에서는 새로운 공지사항을 등록하거나 기존 공지사항의 노출 상태 및 순서를 관리할 수 있습니다.</p><p><img src="'+t+'" alt="image.png"></p><h2 id="_3-2-공지사항-등록" tabindex="-1">3.2. 공지사항 등록 <a class="header-anchor" href="#_3-2-공지사항-등록" aria-label="Permalink to &quot;3.2. 공지사항 등록&quot;">​</a></h2><h3 id="_1-신규-공지사항-등록" tabindex="-1">① 신규 공지사항 등록 <a class="header-anchor" href="#_1-신규-공지사항-등록" aria-label="Permalink to &quot;① 신규 공지사항 등록&quot;">​</a></h3><ol><li><strong>공지사항</strong> 관리 화면으로 이동합니다.</li><li>공지사항 입력 영역에 방문객에게 안내할 내용을 입력합니다.</li><li>작성한 내용을 확인합니다.</li><li><strong>입력</strong> 버튼을 클릭합니다.</li><li>등록한 공지사항이 목록에 표시되는지 확인합니다.</li></ol><h3 id="_2-공지사항-작성-예시" tabindex="-1">② 공지사항 작성 예시 <a class="header-anchor" href="#_2-공지사항-작성-예시" aria-label="Permalink to &quot;② 공지사항 작성 예시&quot;">​</a></h3><table tabindex="0"><thead><tr><th>구분</th><th>작성 예시</th></tr></thead><tbody><tr><td>행사 시간 변경</td><td>우천으로 인해 야외 공연 시작 시간이 오후 3시로 변경되었습니다.</td></tr><tr><td>운영 안내</td><td>행사장 입장 시 현장 안내요원의 안내에 따라 이동해 주세요.</td></tr><tr><td>시설 안내</td><td>행사장 내 임시 화장실은 중앙 안내소 오른쪽에 마련되어 있습니다.</td></tr><tr><td>보상 수령 안내</td><td>스탬프 투어 보상은 중앙 안내소에서 수령할 수 있습니다.</td></tr><tr><td>교통 안내</td><td>행사장 주변 교통 혼잡이 예상되오니 가급적 대중교통을 이용해 주세요.</td></tr></tbody></table><blockquote><p><strong>주의사항</strong></p><p>공지사항은 방문객에게 전달되는 정보이므로 등록 전 행사 날짜, 운영 시간, 장소 등의 내용이 정확한지 확인해 주세요.</p></blockquote><h2 id="_3-3-공지사항-노출-순서-변경" tabindex="-1">3.3. 공지사항 노출 순서 변경 <a class="header-anchor" href="#_3-3-공지사항-노출-순서-변경" aria-label="Permalink to &quot;3.3. 공지사항 노출 순서 변경&quot;">​</a></h2><p>등록된 공지사항은 중요도 및 행사 운영 상황에 따라 노출 순서를 변경할 수 있습니다.</p><h3 id="_1-노출-순서-변경-방법" tabindex="-1">① 노출 순서 변경 방법 <a class="header-anchor" href="#_1-노출-순서-변경-방법" aria-label="Permalink to &quot;① 노출 순서 변경 방법&quot;">​</a></h3><ol><li>현재 노출 중인 공지사항 목록을 확인합니다.</li><li>순서를 변경할 공지사항의 순서 변경 영역을 드래그합니다.</li><li>원하는 위치로 이동합니다.</li><li>변경된 노출 순서를 확인합니다.</li></ol><h2 id="_3-4-공지사항-노출-및-이력-관리" tabindex="-1">3.4. 공지사항 노출 및 이력 관리 <a class="header-anchor" href="#_3-4-공지사항-노출-및-이력-관리" aria-label="Permalink to &quot;3.4. 공지사항 노출 및 이력 관리&quot;">​</a></h2><p>등록된 공지사항은 현재 노출 중인 공지사항과 노출이 종료된 공지사항으로 구분하여 관리할 수 있습니다.</p><h3 id="_1-공지사항-노출-종료" tabindex="-1">① 공지사항 노출 종료 <a class="header-anchor" href="#_1-공지사항-노출-종료" aria-label="Permalink to &quot;① 공지사항 노출 종료&quot;">​</a></h3><p>더 이상 방문객에게 제공할 필요가 없는 공지사항은 노출을 종료할 수 있습니다.</p><ol><li>현재 노출 중인 공지사항 목록을 확인합니다.</li><li>노출을 종료할 공지사항을 선택합니다.</li><li><strong>제거</strong> 버튼을 클릭합니다.</li><li>해당 공지사항이 이력 목록으로 이동했는지 확인합니다.</li></ol><h3 id="_2-종료된-공지사항-다시-노출하기" tabindex="-1">② 종료된 공지사항 다시 노출하기 <a class="header-anchor" href="#_2-종료된-공지사항-다시-노출하기" aria-label="Permalink to &quot;② 종료된 공지사항 다시 노출하기&quot;">​</a></h3><p>노출이 종료된 공지사항은 이력에 보관되며, 필요한 경우 다시 노출할 수 있습니다.</p><ol><li>공지사항 관리 화면에서 이력 목록을 확인합니다.</li><li>다시 노출할 공지사항을 찾습니다.</li><li><strong>게시</strong> 버튼을 클릭합니다.</li><li>해당 공지사항이 현재 노출 목록에 추가되었는지 확인합니다.</li></ol><blockquote><p><strong>참고</strong></p><p>공지사항의 노출을 종료하더라도 기존 내용은 이력에 보관됩니다.</p><p>행사 운영 중 반복적으로 사용하는 안내문은 이력에서 다시 노출하여 활용할 수 있습니다.</p></blockquote><blockquote><p><strong>주의사항</strong></p><p>종료된 공지사항을 다시 노출하는 경우 안내 내용이 현재 행사 운영 상황과 일치하는지 확인해 주세요.</p></blockquote><h2 id="_3-5-공지사항-등록-후-확인" tabindex="-1">3.5. 공지사항 등록 후 확인 <a class="header-anchor" href="#_3-5-공지사항-등록-후-확인" aria-label="Permalink to &quot;3.5. 공지사항 등록 후 확인&quot;">​</a></h2><p>공지사항 등록 및 변경을 완료한 후 방문객용 안내 페이지에서 실제 표시 상태를 확인합니다.</p><h3 id="_1-확인-방법" tabindex="-1">① 확인 방법 <a class="header-anchor" href="#_1-확인-방법" aria-label="Permalink to &quot;① 확인 방법&quot;">​</a></h3><ol><li>방문객용 안내 페이지에 접속합니다.</li><li>공지사항 표시 영역을 확인합니다.</li><li>등록한 공지사항의 내용과 노출 순서를 확인합니다.</li></ol><h3 id="_2-최종-점검-항목" tabindex="-1">② 최종 점검 항목 <a class="header-anchor" href="#_2-최종-점검-항목" aria-label="Permalink to &quot;② 최종 점검 항목&quot;">​</a></h3><ul><li>공지사항의 내용이 정확하게 표시되는지 확인</li><li>중요 공지사항의 노출 순서가 적절한지 확인</li><li>노출을 종료한 공지사항이 표시되지 않는지 확인</li><li>다시 노출한 공지사항이 정상적으로 표시되는지 확인</li><li>모바일 화면에서 공지사항을 확인할 수 있는지 확인</li></ul>',33)])])}const q=l(o,[["render",h]]);export{b as __pageData,q as default};
